(2, 1, '2026-05-26 00:00:00', '2 hours', 'Lwemihla Maphango', 'Seaview training site', 'Pen, paper', '4 hours', 'Lwemihla Maphango', 'Seaview training site', 'Full PPE', 'Lwemihla Maphango', 'LM12345', 'data:image/png;base64,', '2026-05-26 09:32:47', '2026-05-26 20:47:20', '2026-05-27 00:00:00', '09:00 am', 'Seaview training site', 'This was the agreement between learners and assessor', '[{\"id\":1,\"text\":\"Explain to the candidate why your are meeting and the purpose of the assessment.\",\"docs\":\"NQF Framework Assessment process\",\"agreed\":true,\"action\":\"Agreed\"},{\"id\":2,\"text\":\"Discuss the assessment plan in detail.\",\"docs\":\"Assessment strategy\",\"agreed\":true,\"action\":\"Agreed\"},{\"id\":3,\"text\":\"Explain assessment process, show assessment instruments to candidate and describe assessment conditions.\",\"docs\":\"Assessment instruments\",\"agreed\":true,\"action\":\"Agreed\"},{\"id\":4,\"text\":\"Identify the role-players during assessment.\",\"docs\":\"Assessors / Moderator\",\"agreed\":true,\"action\":\"Agreed\"},{\"id\":5,\"text\":\"Describe the evidence required to be declared competent.\",\"docs\":\"Examples of evidence\",\"agreed\":true,\"action\":\"Agreed\"},{\"id\":6,\"text\":\"Explain how evidence will be judged.\",\"docs\":\"-\",\"agreed\":true,\"action\":\"Agreed\"},{\"id\":7,\"text\":\"Explain to the candidate how to prepare: Give candidate summative task description.\",\"docs\":\"Summative task description\",\"agreed\":true,\"action\":\"Agreed\"},{\"id\":8,\"text\":\"Confirm with the candidate what he/she should bring to the assessment.\",\"docs\":\"Detailed briefing on exact requirements\",\"agreed\":true,\"action\":\"Agreed\"},{\"id\":9,\"text\":\"Ensure that candidate understands the procedures of all assessment practices.\",\"docs\":\"Appeals / Moderation / Assessment policy\",\"agreed\":true,\"action\":\"Agreed\"},{\"id\":10,\"text\":\"Ask the candidate if he/she foresees any problems or identify any special needs.\",\"docs\":\"List needs\",\"agreed\":true,\"action\":\"Agreed\"},{\"id\":11,\"text\":\"Check with candidate that he/she clearly understands the assessment procedure.\",\"docs\":\"-\",\"agreed\":true,\"action\":\"Agreed\"}]', NULL, NULL, NULL, NULL),
(3, 2, '2026-05-26 00:00:00', '2 hours', 'Lwemihla Maphango', 'Seaview training site', 'Pens and papers', '4 hours', 'Assessor and Learners', 'Seaview training site', 'Full PPE', 'Lwemihla Maphango', 'A1179', 'data:image/png;base64,', '2026-05-26 20:30:27', '2026-05-26 20:30:29', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
