INSERT INTO "summativeassessmentquestions" ("Id", "SummativeAssessmentId", "QuestionNumber", "QuestionText", "AllocatedMarks", "CreatedAt", "UpdatedAt") VALUES
(1, 1, 1, 'Explain the importance of health and safety policies in the workplace.', 10.00, '2026-05-20 08:29:39.613064', '2026-05-20 08:29:39.613096'),
(2, 1, 2, 'Discuss the responsibilities of employers and employees in maintaining workplace safety.', 15.00, '2026-05-20 08:29:39.631249', '2026-05-20 08:29:39.631250'),
(3, 1, 3, 'Describe the steps that should be followed during an emergency evacuation.', 10.00, '2026-05-20 08:29:39.631311', '2026-05-20 08:29:39.631311'),
(4, 1, 4, 'Explain how risk assessments help prevent workplace accidents.', 10.00, '2026-05-20 08:29:39.631340', '2026-05-20 08:29:39.631341'),
(5, 1, 5, 'Discuss the importance of PPE and the consequences of not using it correctly.', 10.00, '2026-05-20 08:29:39.631361', '2026-05-20 08:29:39.631361'),
(6, 2, 1, 'Discuss the impact of poor waste management on the environment and community health', 5.00, '2026-05-22 14:24:24.389413', '2026-05-22 14:24:24.389445'),
(7, 2, 2, 'Explain how organisations can implement environmentally sustainable practices in the workplace', 5.00, '2026-05-22 14:24:24.393048', '2026-05-22 14:24:24.393049'),
(8, 2, 3, 'Analyse the importance of environmental awareness training for employees.', 8.00, '2026-05-22 14:24:24.393087', '2026-05-22 14:24:24.393087'),
(9, 2, 4, 'Describe the legal and organisational responsibilities related to environmental protection.', 6.00, '2026-05-22 14:24:24.393097', '2026-05-22 14:24:24.393098'),
(10, 2, 5, 'Evaluate the effectiveness of recycling programmes in reducing environmental damage.', 6.00, '2026-05-22 14:24:24.393108', '2026-05-22 14:24:24.393108'),
(11, 3, 1, 'Explain how poor site practice can affect safety, productivity, and quality of work.', 5.00, '2026-05-23 17:28:58.622027', '2026-05-23 17:28:58.622082'),
(12, 3, 2, 'Discuss the importance of inspecting tools and equipment before use on site.', 5.00, '2026-05-23 17:28:58.624363', '2026-05-23 17:28:58.624364'),
(13, 3, 3, 'Identify five common site hazards and explain how each hazard can be prevented.', 10.00, '2026-05-23 17:28:58.625966', '2026-05-23 17:28:58.625966'),
(14, 3, 4, 'Compare hand tools and power tools, including advantages and disadvantages of each.', 15.00, '2026-05-23 17:28:58.626039', '2026-05-23 17:28:58.626040'),
(15, 3, 5, 'Demonstrate knowledge of workplace procedures by explaining the correct use, maintenance, and storage of tools and equipment on site.', 10.00, '2026-05-23 17:28:58.626120', '2026-05-23 17:28:58.626120'),
(16, 4, 1, 'Explain the importance of technical drawings in communicating information on a worksite.', 4.00, '2026-05-23 17:38:37.358872', '2026-05-23 17:38:37.358872'),
(17, 4, 2, 'Interpret a basic technical drawing and describe the meaning of symbols, lines, and dimensions used.', 5.00, '2026-05-23 17:38:37.359288', '2026-05-23 17:38:37.359288'),
(18, 4, 3, 'Discuss the relationship between science and technology in engineering or construction environments.', 6.00, '2026-05-23 17:38:37.359360', '2026-05-23 17:38:37.359360'),
(19, 4, 4, 'Calculate and explain the effects of force, mass, and motion in a practical workplace situation.', 10.00, '2026-05-23 17:38:37.359382', '2026-05-23 17:38:37.359382'),
(20, 4, 5, 'Demonstrate an understanding of applied science principles by explaining how measurements, calculations, and scientific concepts are used to solve workplace problems.', 15.00, '2026-05-23 17:38:37.359419', '2026-05-23 17:38:37.359419'),
(21, 5, 1, 'Explain the importance of proper water drainage in construction and civil works projects.', 5.00, '2026-05-23 17:49:10.393557', '2026-05-23 17:49:10.393558'),
(22, 5, 2, 'Describe the steps involved in preparing and carrying out an excavation for drainage installation.', 5.00, '2026-05-23 17:49:10.393698', '2026-05-23 17:49:10.393699'),
(23, 5, 3, 'Discuss the dangers associated with excavation work and explain methods used to control these risks.', 6.00, '2026-05-23 17:49:10.393729', '2026-05-23 17:49:10.393729'),
(24, 5, 4, 'Explain how incorrect pipe levels and poor drainage design can affect a drainage system.', 5.00, '2026-05-23 17:49:10.393769', '2026-05-23 17:49:10.393769'),
(25, 5, 5, 'Demonstrate knowledge of drainage excavation by describing the tools, materials, safety procedures, and installation methods used on site.', 4.00, '2026-05-23 17:49:10.393810', '2026-05-23 17:49:10.393810'),
(26, 6, 1, 'Explain the functions of above-ground and below-ground drainage systems in buildings and construction sites.', 5.00, '2026-05-23 17:56:00.094535', '2026-05-23 17:56:00.094535'),
(27, 6, 2, 'Describe the installation process of a below-ground drainage system, including materials and tools used.', 5.00, '2026-05-23 17:56:00.094628', '2026-05-23 17:56:00.094628'),
(28, 6, 3, 'Discuss the importance of maintaining correct gradients and pipe alignment in drainage systems.', 5.00, '2026-05-23 17:56:00.094644', '2026-05-23 17:56:00.094644'),
(29, 6, 4, 'Explain common problems that occur in drainage systems and how they can be prevented or repaired.', 5.00, '2026-05-23 17:56:00.094657', '2026-05-23 17:56:00.094657'),
(30, 6, 5, 'Demonstrate understanding of drainage systems by explaining the components, operation, maintenance, and safety requirements for both above-ground and below-ground drainage installations.', 15.00, '2026-05-23 17:56:00.094688', '2026-05-23 17:56:00.094688');
